const body = $input.first()?.json?.body || $input.first()?.json || {};
const headers = $input.first()?.json?.headers || {};

const message = body.message || body.edited_message;
if (!message || typeof message !== 'object') {
  return [{ json: { isValid: false, reason: 'No message object in payload' } }];
}

if (!message.text || message.text.trim() === '') {
  return [{ json: { isValid: false, reason: 'Non-text message ignored' } }];
}

const fromUser = message.from || {};
const chat = message.chat || {};
const firstName = fromUser.first_name || chat.first_name || '';
const lastName = fromUser.last_name || chat.last_name || '';
const fullName = [firstName, lastName].filter(Boolean).join(' ') || fromUser.username || 'Telegram User';

return [{
  json: {
    isValid: true,
    telegram_message_id: String(message.message_id || ''),
    chat_id: String(chat.id || ''),
    telegram_username: fromUser.username ? '@' + fromUser.username : '',
    customer_name: fullName,
    message_text: message.text.trim(),
    message_type: 'text',
    timestamp: message.date
  }
}];

const extracted = ($('Code - Extract & Validate Message Info').first()?.json || {});
const history = ($('DB - Load History & Knowledge').first()?.json?.history || []);

const systemPrompt = `=== SYSTEM ROLE & IDENTITY ===
You are the official AI Sales & Lead Qualification Specialist representing Apex Enterprise Solutions on Telegram.
- Company Name: Apex Enterprise Solutions
- Company Specialization: Custom Odoo ERP Development & Integration, Telegram & WhatsApp AI Chatbot Automation, Business Process Engineering.
- Persona: Professional, polite, articulate, dynamic, helpful, and customer-focused.

=== CRITICAL DIALOGUE & LEAD QUALIFICATION RULES ===
1. CONVERSATION MEMORY & CONTINUITY:
   - Review the RECENT MESSAGE HISTORY carefully.
   - NEVER ask for information the customer has ALREADY provided in previous messages.
   - If customer asks for quotation, call, or pricing, confirm politely and acknowledge warmly.

2. MULTILINGUAL SUPPORT (ENGLISH & BANGLA):
   - ALWAYS respond in the SAME language used by the customer.

3. HANDLING OFF-TOPIC QUESTIONS:
   - Gently refuse off-topic questions and redirect to Apex Enterprise Solutions services.

4. HUMAN HANDOVER TRIGGER:
   Set human_handoff = true and lead_ready = true if customer provides a phone number OR explicitly requests a call / quotation.

5. COMPREHENSIVE LEAD DATA EXTRACTION:
   Extract ALL available details from conversation history into the 'lead' object:
   - name, phone, email, company, product_interest, requirement, budget, timeline, location, preferred_contact_time, notes

=== REQUIRED OUTPUT FORMAT ===
STRICT VALID JSON ONLY. No markdown.

{
  "reply": "Professional dynamic reply",
  "lead_ready": boolean,
  "human_handoff": boolean,
  "handoff_reason": "",
  "lead_score": number,
  "lead": {
    "name": "", "chat_id": "", "telegram_username": "",
    "phone": "", "email": "", "company": "",
    "product_interest": "", "requirement": "",
    "budget": "", "timeline": "", "location": "",
    "preferred_contact_time": "", "notes": ""
  }
}`;

const userContent = `Customer Name: ${extracted.customer_name || 'Customer'}
Chat ID: ${extracted.chat_id || ''}
Telegram Username: ${extracted.telegram_username || ''}
Latest Customer Message: ${extracted.message_text || ''}

Chronological Message History:
${JSON.stringify(history)}`;

const requestBody = {
  system_instruction: { parts: [{ text: systemPrompt }] },
  contents: [{ parts: [{ text: userContent }] }],
  generationConfig: { temperature: 0.3, response_mime_type: "application/json" }
};

return [{ json: { payload: requestBody } }];

const extracted = ($('Code - Extract & Validate Message Info').first()?.json || {});
const geminiRes = $input.first()?.json || {};

let rawText = '';
let apiError = '';
try {
  if (geminiRes.error) {
    apiError = JSON.stringify(geminiRes.error);
  } else if (geminiRes.candidates?.[0]?.content?.parts) {
    rawText = geminiRes.candidates[0].content.parts[0].text || '';
  }
} catch (e) { apiError = String(e); }

let parsed = null;
if (rawText) {
  try {
    const cleaned = rawText.replace(/```json/gi, '').replace(/```/g, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {}
}

let fallbackUsed = false;
if (!parsed || typeof parsed !== 'object' || !parsed.reply) {
  fallbackUsed = true;
  const msgText = extracted.message_text || '';
  const isBangla = /[\u0980-\u09FF]/.test(msgText);
  parsed = {
    reply: isBangla
      ? `ধন্যবাদ ${extracted.customer_name || ''}! আপনার মেসেজটি পেয়েছি। কীভাবে সাহায্য করতে পারি?`
      : `Hello ${extracted.customer_name || ''}! Thank you for reaching out to Apex Enterprise Solutions. How can we assist you today?`,
    lead_ready: false, human_handoff: false, handoff_reason: '', lead_score: 20,
    lead: { name: extracted.customer_name || '', chat_id: extracted.chat_id || '', telegram_username: extracted.telegram_username || '', requirement: msgText }
  };
}

if (!parsed.lead) parsed.lead = {};
if (!parsed.lead.chat_id) parsed.lead.chat_id = extracted.chat_id || '';
if (!parsed.lead.telegram_username) parsed.lead.telegram_username = extracted.telegram_username || '';
if (!parsed.lead.name) parsed.lead.name = extracted.customer_name || 'Telegram User';

// Extract phone from message text if AI didn't catch it
const msgText = extracted.message_text || '';
if (!parsed.lead.phone) {
  const phoneMatch = msgText.match(/(?:\+?880|0)?1[3-9]\d{8}|[0-9]{11}/);
  if (phoneMatch) parsed.lead.phone = phoneMatch[0].trim();
}

return [{ json: { success: true, ai_output: parsed, _fallback_used: fallbackUsed, _api_error: apiError } }];

const extracted = ($('Code - Extract & Validate Message Info').first()?.json || {});
const parseNode = ($('Code - Parse AI Response').first()?.json || {});
const aiOutput = parseNode.ai_output || {};
const leadData = aiOutput.lead || {};

const chatId = String(extracted.chat_id || leadData.chat_id || '');
const telegramUsername = String(extracted.telegram_username || leadData.telegram_username || '');
const telegramMsgId = String(extracted.telegram_message_id || '');
const customerName = leadData.name || extracted.customer_name || 'Telegram User';
const msgText = extracted.message_text || '';
const phone = leadData.phone || '';
const productInterest = leadData.product_interest || leadData.requirement || 'Odoo ERP System';
const requirement = leadData.requirement || msgText || 'Odoo ERP Customization';
const leadScore = typeof aiOutput.lead_score === 'number' ? aiOutput.lead_score : 80;
const aiReply = aiOutput.reply || '';
const handoffReason = aiOutput.handoff_reason || (aiOutput.human_handoff ? 'Customer requested call/quotation' : 'Standard Inquiry');
const nowStr = new Date().toISOString().replace('T', ' ').substring(0, 19);

return [{ json: {
  odooAuthPayload: {
    jsonrpc: '2.0', method: 'call',
    params: { service: 'common', method: 'authenticate', args: ['odoo_db1', 'admin@example.com', 'admin_password', {}] },
    id: 1
  },
  chatId, telegramUsername, telegramMsgId, customerName, msgText,
  phone, productInterest, requirement, leadScore, aiReply, handoffReason, nowStr,
  leadData
}}];

const uid = $('HTTP - Odoo Auth').first()?.json?.result;
const leadIds = $('HTTP - Odoo Search Lead').first()?.json?.result || [];
const prep = $('Code - Prepare Odoo Payload').first()?.json || {};

if (!uid) {
  return [{ json: { status: 'Odoo Auth Failed - uid missing', uid: uid } }];
}

const leadFields = {
  name: `Telegram Lead - ${prep.customerName} (${prep.chatId})`,
  contact_name: prep.customerName,
  description: `Latest Message: ${prep.msgText}\nPhone: ${prep.phone}\nRequirement: ${prep.requirement}\nAI Summary: ${prep.aiReply}\nHandoff: ${prep.handoffReason}\nScore: ${prep.leadScore}`,
  type: 'opportunity',
  user_id: uid,
  x_telegram_chat_id: prep.chatId,
  x_telegram_username: prep.telegramUsername,
  x_telegram_message_id: prep.telegramMsgId,
  x_last_message_time: prep.nowStr,
  x_ai_lead_score: prep.leadScore,
  x_product_interest: prep.productInterest,
  x_customer_budget: prep.leadData?.budget || 'Negotiable / Custom Quote',
  x_required_timeline: prep.leadData?.timeline || 'Within 2-4 Weeks',
  x_customer_location: prep.leadData?.location || 'Bangladesh',
  x_preferred_contact_time: prep.leadData?.preferred_contact_time || (prep.phone ? prep.msgText : 'Business Hours'),
  x_customer_requirement: prep.requirement,
  x_ai_summary: prep.aiReply,
  x_handoff_reason: prep.handoffReason
};

if (prep.phone) leadFields.phone = prep.phone;
if (prep.leadData?.email) leadFields.email_from = prep.leadData.email;
if (prep.leadData?.company) leadFields.partner_name = prep.leadData.company;

const isUpdate = leadIds.length > 0;
const method = isUpdate ? 'write' : 'create';
const args = isUpdate
  ? [leadIds, leadFields]
  : [leadFields];

return [{ json: {
  odooWritePayload: {
    jsonrpc: '2.0', method: 'call',
    params: { service: 'object', method: 'execute_kw', args: ['odoo_db1', uid, 'admin_password', 'crm.lead', method, [args]] },
    id: 3
  },
  uid, leadIds, isUpdate, chatId: prep.chatId, phone: prep.phone
}}];
